import json

for t in ['{"a": 1}',
          "{'a': 1}",
          '[1, 2, 3,]',
          '{"a": True}']:
    try:
        print(json.loads(t))
    except json.JSONDecodeError:
        print("ungültig:", t)

# {'a': 1}
# ungültig: {'a': 1}
# ungültig: [1, 2, 3,]
# ungültig: {"a": True}

d = {"name": "Jörg",
     "aktiv": True,
     "note": None}
print(json.dumps(d))
# {"name": "J\u00f6rg", "aktiv":
#  true, "note": null}

print(json.dumps(d,
      ensure_ascii=False))
# {"name": "Jörg", "aktiv":
#  true, "note": null}
